def _units_dict():
    return {
        0: 'zero', 1: 'one', 2: 'two', 3: 'three', 4: 'four',
        5: 'five', 6: 'six', 7: 'seven', 8: 'eight', 9: 'nine',
        10: 'ten', 11: 'eleven', 12: 'twelve', 13: 'thirteen',
        14: 'fourteen', 15: 'fifteen', 16: 'sixteen',
        17: 'seventeen', 18: 'eighteen', 19: 'nineteen',
        20: 'twenty', 30: 'thirty', 40: 'forty', 50: 'fifty',
        60: 'sixty', 70: 'seventy', 80: 'eighty', 90: 'ninety'
    }

_units = _units_dict()

def _sub_three_digits(m):
    # m is 1-999
    parts = []
    hundreds = m // 100
    if hundreds:
        parts.append(_units[hundreds] + ' hundred')
    remainder = m % 100
    if remainder:
        if remainder < 20:
            parts.append(_units[remainder])
        else:
            tens = remainder // 10 * 10
            unit = remainder % 10
            word = _units[tens]
            if unit:
                word += '-' + _units[unit]
            parts.append(word)
    return ' '.join(parts)

def number_to_words(n):
    if type(n) is not int:
        raise ValueError('Input must be an int')
    if n < 0 or n > 999_999_999:
        raise ValueError('Input must be between 0 and 999999999')
    if n == 0:
        return 'zero'
    words = []
    millions = n // 1_000_000
    if millions:
        words.append(_sub_three_digits(millions) + ' million')
        n %= 1_000_000
    thousands = n // 1000
    if thousands:
        words.append(_sub_three_digits(thousands) + ' thousand')
        n %= 1000
    if n:
        words.append(_sub_three_digits(n))
    return ' '.join(words)

def test():
    cases = [
        (0, 'zero'),
        (13, 'thirteen'),
        (21, 'twenty-one'),
        (105, 'one hundred five'),
        (1000, 'one thousand'),
        (1234567, 'one million two hundred thirty-four thousand five hundred sixty-seven'),
        (101, 'one hundred one'),
        (110, 'one hundred ten'),
        (115, 'one hundred fifteen'),
        (200, 'two hundred'),
        (2000, 'two thousand'),
        (2001, 'two thousand one'),
        (123, 'one hundred twenty-three'),
        (1001, 'one thousand one'),
        (1010, 'one thousand ten'),
        (1100, 'one thousand one hundred'),
        (999999999, 'nine hundred ninety-nine million nine hundred ninety-nine thousand nine hundred ninety-nine'),
        (500000, 'five hundred thousand'),
        (500001, 'five hundred thousand one'),
        (1000000, 'one million'),
        (999999, 'nine hundred ninety-nine thousand nine hundred ninety-nine'),
    ]
    for n, expected in cases:
        assert number_to_words(n) == expected, f'Failed for {n}: got {number_to_words(n)} expected {expected}'
    # error cases
    try:
        number_to_words(-1)
        raise AssertionError('Expected ValueError for -1')
    except ValueError:
        pass
    try:
        number_to_words(1000000000)
        raise AssertionError('Expected ValueError for 1000000000')
    except ValueError:
        pass
    try:
        number_to_words(3.14)
        raise AssertionError('Expected ValueError for 3.14')
    except ValueError:
        pass
    try:
        number_to_words('5')
        raise AssertionError('Expected ValueError for string')
    except ValueError:
        pass
    try:
        number_to_words(True)
        raise AssertionError('Expected ValueError for bool')
    except ValueError:
        pass
    print('ALL TESTS PASSED')

if __name__ == '__main__':
    test()

